    if !std::io::stdin().is_terminal() {
        return Err("habit renew requires the author's interactive terminal".into());
    }
    if id <= 0 || !super::collection::valid_id(revision) {
        return Err("renewal requires a positive habit ID and full review revision".into());
    }
    let path = store::ProfileStore::db_path().ok_or("could not resolve home directory")?;
    store::ProfileStore::open_read_only(&path)?;
    let (receipt, _) = publish_profile(
        &path,
        &profile_path()?,
        false,
        |db| Ok(db.renew_habit(id, revision)?),
        |_| None,
    )?;
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({"renewal":receipt,
            "note":"A new generation copies only the description. Cite evidence and review it separately. Renewal does not establish a return of the behavior or replace another active habit. Exact retries return the existing child's current stored status."
        }))?
    );
    Ok(())

fn script_specifier(
    node: Node<'_>,
    source: &str,
    language: &str,
    libraries: &mut BTreeSet<String>,
) {
    if node.kind() == "string" {
        if let Ok(specifier) = node.utf8_text(source.as_bytes()) {
            insert(libraries, language, &format!("import x from {specifier}"));
        }
    }
}

//! Declarative, revision-bound fact ingestion for community extensions.
//!
//! Producers submit a strict JSON manifest. Mastermind validates the complete
//! document, repository/revision binding, source files, and provenance
//! artifacts before atomically replacing one producer dataset. Imported data
//! never selects SQL, registers MCP handlers, or changes the Tree-sitter graph.

//! Explicit semantic judgments over a mechanically held task revision.
//!
//! A local reviewer assertion is not proof of truth, identity, independence, or
//! model use. The controller validates its shape, evidence references and
//! freshness; it never manufactures a positive judgment from passing checks.

fn add_context_estimates(
    builder: &mut WorkflowAuditBuilder,
    component: &LoadedWorkflowComponent,
    component_by_id: &BTreeMap<&str, &LoadedWorkflowComponent>,
    schema_bytes: &BTreeMap<String, usize>,
    known_grants: &BTreeSet<String>,
) {
    builder.add_context_estimate(WorkflowContextEstimate {
        component_id: component.node_id.clone(),
        scenario: "agent_body".into(),
        bytes: Some(component.text_bytes),
        estimated_tokens: Some(estimated_tokens(component.text_bytes)),
        components: vec![component.path.clone()],
        unavailable: Vec::new(),
    });
    let mut skill_ids = BTreeSet::new();
    if let Some(workflow) = &component.workflow {
        skill_ids.extend(workflow.skills.iter().map(|relation| relation.id.clone()));
    }
    if component.kind == "agent" {
        skill_ids.extend(component.wikilinks.iter().cloned());
    }
    for skill_id in skill_ids {
        if let Some(skill) = component_by_id
            .get(skill_id.as_str())
            .filter(|target| target.kind == "skill")
        {
            builder.add_context_estimate(WorkflowContextEstimate {
                component_id: component.node_id.clone(),
                scenario: "advisory_skill_if_loaded".into(),
                bytes: Some(skill.text_bytes),
                estimated_tokens: Some(estimated_tokens(skill.text_bytes)),
                components: vec![format!("skill:{skill_id}")],
                unavailable: Vec::new(),
            });
        } else {
            builder.add_context_estimate(WorkflowContextEstimate {
                component_id: component.node_id.clone(),
                scenario: "advisory_skill_if_loaded".into(),
                bytes: None,
                estimated_tokens: None,
                components: Vec::new(),
                unavailable: vec![format!("skill:{skill_id}")],
            });
        }
    }
    let known_schema_total = known_grants
        .iter()
        .filter_map(|tool| schema_bytes.get(tool))
        .sum::<usize>();
    builder.add_context_estimate(WorkflowContextEstimate {
        component_id: component.node_id.clone(),
        scenario: "known_mmcg_schema".into(),
        bytes: Some(known_schema_total),
        estimated_tokens: Some(estimated_tokens(known_schema_total)),
        components: known_grants
            .iter()
            .map(|tool| format!("tool:{tool}"))
            .collect(),
        unavailable: Vec::new(),
    });
    let built_in = component
        .tools
        .iter()
        .filter(|tool| !tool.starts_with("mcp__"))
        .cloned()
        .collect::<Vec<_>>();
    if !built_in.is_empty() {
        builder.add_context_estimate(WorkflowContextEstimate {
            component_id: component.node_id.clone(),
            scenario: "built_in_schema_unknown".into(),
            bytes: None,
            estimated_tokens: None,
            components: Vec::new(),
            unavailable: built_in,
        });
    }
}

fn estimated_tokens(bytes: usize) -> usize {
    bytes.saturating_add(3) / 4
}

